            } else {
                toggleBtn.textContent = "Switch to Night";
                toggleBtn.classList.remove('active');

                // Visuals
                scene.background = dayColor;
                scene.fog.color = dayColor;
                scene.fog.density = 0.015;
                ambientLight.intensity = 0.6;
                sunLight.intensity = 1.5;
                lighthouse.beamMesh.visible = false;
                lighthouse.spotLight.intensity = 100;
            }
        });

        // --- Animation Loop ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // 1. Water Waves (Displacement)
            const positions = waterGeo.attributes.position;
            for (let i = 0; i < positions.count; i++) {
                const x = positions.getX(i);
                const z = positions.getZ(i);
                // Combine waves for organic look
                const yVal = Math.sin(x * 0.5 - time * 1.5) * 0.3 + 
                             Math.cos(z * 0.3 - time * 1.2) * 0.4 +
                             Math.sin(x * 0.2 + z * 0.5 - time * 0.8) * 0.1;
                positions.setY(i, yVal);
            }
            positions.needsUpdate = true;

            // 2. Palm Trees Sway
            const swaySpeed = 0.8;
            lerpObject(lighthouse.group, new THREE.Vector3(6, 0, 10), 0.05);
            if(!isNight) {
                 const sway = Math.sin(time * swaySpeed);
                 lighthouse.group.position.x = THREE.MathUtils.lerp(lighthouse.group.position.x, 6 + sway * 0.2, 0.1);
            }

            // 3. Lighthouse Rotation
            lighthouse.group.rotation.y = time * 0.2;

            controls.update();
            renderer.render(scene, camera);
        }

        // Helper: Smooth movement interpolation
        function lerpObject(obj, target, speed) {
            obj.position.x = obj.position.x + (target.x - obj.position.x) * speed;
            obj.position.y = obj.position.y + (target.y - obj.position.y) * speed;
            obj.position.z = obj.position.z + (target.z - obj.position.z) * speed;
        }

        // Handle Window Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
