#!/usr/bin/env python3
"""
ledger.py - A CSV transaction ledger analyzer CLI tool

Usage:
    python ledger.py summary --csv transactions.csv --month YYYY-MM [--category CATEGORY]
    python ledger.py top --csv transactions.csv --n 5
    python ledger.py budget --csv transactions.csv --budget budget.json --limit YYYY-MM
"""

import argparse
import csv
import json
import sys
from dataclasses import dataclass, field
from datetime import datetime
from io import StringIO
from pathlib import Path
from typing import Optional


@dataclass
class Transaction:
    date: datetime
    payee: str
    amount: float
    category: str
    _sign: int = field(init=False)

    def __post_init__(self):
        self._sign = 1 if self.amount >= 0 else -1

    @property
    def is_expense(self) -> bool:
        return self._sign == -1

    def __str__(self) -> str:
        return (
            f"[{self.date.strftime('%Y-%m-%d')}] "
            f"{self.payee} | {self.category} | ${abs(self.amount):.2f}"
        )


@dataclass
class CategorySummary:
    category: str
    month: str
    amount: float = 0.0
    count: int = 0

    def add(self, transaction: Transaction) -> None:
        if transaction.is_expense:
            self.amount += abs(transaction.amount)
            self.count += 1

    def to_dict(self) -> dict:
        return {
            "category": self.category,
            "month": self.month,
            "total": round(self.amount, 2),
            "count": self.count,
        }


def parse_amount(value: str) -> float:
    try:
        return float(value.strip())
    except ValueError:
        raise ValueError(f"Invalid amount '{value}'")


def parse_date(value: str) -> datetime:
    for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%d/%m/%Y", "%Y/%m/%d"):
        try:
            return datetime.strptime(value.strip(), fmt)
        except ValueError:
            continue
    raise ValueError(f"Invalid date format '{value}'")


def read_csv(path: str) -> list[Transaction]:
    """Read CSV and return list of Transaction objects."""
    transactions: list[Transaction] = []
    path_obj = Path(path)
    if not path_obj.is_file():
        raise FileNotFoundError(f"CSV file not found: {path}")

    with open(path_obj, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        if reader.fieldnames is None:
            raise ValueError("CSV file is empty or has no header")

        required_fields = {"date", "payee", "amount", "category"}
        if not required_fields.issubset(set(reader.fieldnames)):
            missing = required_fields - set(reader.fieldnames)
            raise ValueError(
                f"Missing required CSV columns: {', '.join(missing)}"
            )

        expected = reader.fieldnames[:]
        for line_num, row in enumerate(reader, start=2):
            try:
                date = parse_date(row["date"])
                payee = row["payee"].strip()
                amount = parse_amount(row["amount"])
                category = row["category"].strip()

                if not payee:
                    raise ValueError(f"Line {line_num}: Empty payee")
                if not category:
                    raise ValueError(f"Line {line_num}: Empty category")

                transactions.append(Transaction(date, payee, amount, category))
            except ValueError as e:
                raise RuntimeError(f"Error on line {line_num}: {e}") from None
    return transactions


def cmd_summary(
    csv_path: str,
    month: Optional[str] = None,
    category: Optional[str] = None,
) -> int:
    """Generate totals per category and optionally month."""
    try:
        transactions = read_csv(csv_path)
    except (FileNotFoundError, ValueError, RuntimeError) as e:
        print(f"Error reading CSV: {e}", file=sys.stderr)
        return 1

    if month:
        month_pattern = f"{month}-%"
    else:
        month_pattern = "%"

    summaries: dict[str, dict[str, CategorySummary]] = {}
    current_month = None

    for t in transactions:
        date_str = t.date.strftime("%Y-%m")
        if month and not date_str.startswith(month_pattern):
            continue

        summaries.setdefault(t.category, {}).setdefault(date_str, CategorySummary(
            category=t.category,
            month=date_str,
        )).add(t)

    total_categories = len(summaries) if summaries else 0
    for cat, months in sorted(summaries.items()):
        for month in sorted(months.keys()):
            summary = months[month].to_dict()
            print(f"{month}\t{cat}\t${summary['total']:.2f}\t({summary['count']} txns)")

    print("\n=== OVERALL BY CATEGORY ===", file=sys.stderr)
    if month:
        month_prefix = f"{month}-"
        total = sum(
            s.amount
            for cats in summaries.values()
            for s in cats.values()
            if s.month.startswith(month_prefix)
        )
        counts = sum(
            s.count
            for cats in summaries.values()
            for s in cats.values()
            if s.month.startswith(month_prefix)
        )
    else:
        total = sum(
            s.amount for cats in summaries.values() for s in cats.values()
        )
        counts = sum(
            s.count for cats in summaries.values() for s in cats.values()
        )
    print(f"Total Expenses: ${total:.2f} ({counts} transactions)", file=sys.stderr)

    return 0


def cmd_top(
    csv_path: str,
    n: int,
) -> int:
    """Show the largest N expense transactions."""
    try:
        transactions = read_csv(csv_path)
    except (FileNotFoundError, ValueError, RuntimeError) as e:
        print(f"Error reading CSV: {e}", file=sys.stderr)
        return 1

    if not transactions:
        print("No transactions found.", file=sys.stderr)
        return 0

    expenses = [t for t in transactions if t.is_expense]
    expenses.sort(key=lambda t: t.amount, reverse=True)
    top_n = expenses[:n]

    if not top_n:
        print("No expense transactions found.", file=sys.stderr)
        return 0

    print(f"Top {len(top_n)} Expenses:\n" + "-" * 60)
    for i, t in enumerate(top_n, start=1):
        print(f"{i:3}. {t}")
    print("-" * 60)
    return 0


def cmd_budget(
    csv_path: str,
    budget_file: str,
    limit: Optional[str] = None,
) -> int:
    """Compare expenses against a JSON budget and flag overspends."""
    try:
        transactions = read_csv(csv_path)
    except (FileNotFoundError, ValueError, RuntimeError) as e:
        print(f"Error reading CSV: {e}", file=sys.stderr)
        return 1

    try:
        with open(budget_file, "r", encoding="utf-8") as f:
            budget_data = json.load(f)
    except FileNotFoundError:
        print(f"Budget file not found: {budget_file}", file=sys.stderr)
        return 1
    except json.JSONDecodeError as e:
        print(f"Invalid JSON in budget file: {e}", file=sys.stderr)
        return 1

    if not isinstance(budget_data, dict) or "budget" not in budget_data:
        print("Budget file must contain a top-level 'budget' object.", file=sys.stderr)
        return 1

    budget = budget_data.get("budget", {})
    if not isinstance(budget, dict):
        print("'budget' must be an object.", file=sys.stderr)
        return 1

    if limit:
        month_pattern = f"{limit}-%"
    else:
        month_pattern = "%"

    # Validate categories and build expected set
    expected_categories = set(budget.keys())
    if not expected_categories:
        print("No budget categories defined.", file=sys.stderr)
        return 1

    # Accumulate expenses by category+month
    expenses: dict[str, float] = {}
    for t in transactions:
        if t.is_expense:
            key = (t.category, t.date.strftime("%Y-%m"))
            expenses[key] = expenses.get(key, 0) + abs(t.amount)

    print("=== BUDGET ANALYSIS ===\n")
    print(f"{'Category':<20} {'Month':<12} {'Planned':<10} {'Actual':<10} {'Status'}")
    print("-" * 64)

    flagged_count = 0
    for cat, monthly_limit in sorted(budget.items()):
        if not isinstance(monthly_limit, (int, float)):
            print(f"Warning: Invalid limit for {cat}", file=sys.stderr)
            continue
        for month, actual in sorted(expenses.items(), key=lambda x: x[0]):
            if not month.startswith(month_pattern):
                continue
            status = "OK"
            if actual > monthly_limit:
                status = "OVERSPEND"
                flagged_count += 1
            print(
                f"{cat:<20} {month:<12} ${monthly_limit:>9.2f} ${actual:>9.2f} {status}"
            )

    # Print summary for any categories that were not in actuals
    for cat in sorted(expected_categories):
        if cat not in expenses:
            print(f"{cat:<20} N/A         ${budget[cat]:>9.2f} $0.00   OK")

    print("-" * 64)
    print(f"\nTotal flagged overspends: {flagged_count}")

    return 1 if flagged_count else 0


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(
        prog="ledger.py",
        description="Analyze CSV transaction data",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
Examples:
  python ledger.py summary --csv transactions.csv
  python ledger.py top --csv transactions.csv --n 10
  python ledger.py budget --csv transactions.csv --budget budget.json --limit 2023-10
        """
    )
    parser.add_argument("--csv", required=True, help="Path to CSV file")
    subparsers = parser.add_subparsers(dest="command", required=True)

    # Summary subcommand
    summary_parser = subparsers.add_parser("summary", help="Category & monthly summary")
    summary_parser.add_argument(
        "--month", type=str, help="Filter by year-month (YYYY-MM)"
    )
    summary_parser.add_argument(
        "--category", type=str, help="Filter by category only"
    )
    summary_parser.set_defaults(func=cmd_summary)

    # Top subcommand
    top_parser = subparsers.add_parser("top", help="Largest N expenses")
    top_parser.add_argument(
        "--n", type=int, default=5, help="Number of top expenses"
    )
    top_parser.set_defaults(func=cmd_top)

    # Budget subcommand
    budget_parser = subparsers.add_parser(
        "budget", help="Compare expenses against budget JSON"
    )
    budget_parser.add_argument(
        "--budget", type=str, required=True,
        help="Path to JSON budget file"
    )
    budget_parser.add_argument(
        "--limit", type=str, help="Year-month to filter (YYYY-MM)"
    )
    budget_parser.set_defaults(func=cmd_budget)

    args = parser.parse_args(argv)

    try:
        return args.func(csv_path=args.csv,
                        month=args.month,
                        category=args.category,
                        n=args.n,
                        budget_file=args.budget,
                        limit=args.limit)
    except KeyboardInterrupt:
        print("\nInterrupted.", file=sys.stderr)
        return 130
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
