import json
import unittest
from pathlib import Path
from tempfile import TemporaryDirectory

from ledger import Transaction, read_csv, cmd_summary, cmd_top, cmd_budget


class TestTransaction(unittest.TestCase):
    def test_expense_detection(self):
        t1 = Transaction(datetime(2023, 10, 1), "Shell", -25.0, "Transport")
        t2 = Transaction(datetime(2023, 10, 1), "Gift", 50.0, "Other")
        self.assertTrue(t1.is_expense)
        self.assertFalse(t2.is_expense)

    def test_str_format(self):
        t = Transaction(datetime(2023, 5, 15), "Starbucks", -6.50, "Food")
        expected = "[2023-05-15] Starbucks | Food | $6.50"
        self.assertEqual(str(t), expected)


class TestCsvParsing(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.csv_content = """date,payee,amount,category
2023-10-01,Shell,-25.00,Transport
2023-10-02,Amy,+100.00,Other
2023-10-03,Starbucks,-6.50,Food
2023-10-10,Aldi,-42.99,Food
2023-11-01,Shell,-30.00,Transport
"""

    def _write_csv(self, filename):
        path = Path(filename)
        path.write_text(self.csv_content, encoding="utf-8")
        return path

    def test_read_csv_basic(self):
        with TemporaryDirectory() as tmpdir:
            path = self._write_csv(Path(tmpdir) / "test.csv")
            records = read_csv(str(path))
            self.assertEqual(len(records), 5)

    def test_read_csv_invalid_date(self):
        bad_csv = self.csv_content.replace("2023-10-01", "not-a-date")
        with TemporaryDirectory() as tmpdir:
            path = Path(tmpdir) / "bad.csv"
            path.write_text(bad_csv, encoding="utf-8")
            with self.assertRaises(RuntimeError):
                read_csv(str(path))

    def test_read_csv_missing_column(self):
        short_csv = "date,payee,amount\n2023-10-01,Shell,-25"
        with TemporaryDirectory() as tmpdir:
            path = Path(tmpdir) / "short.csv"
            path.write_text(short_csv, encoding="utf-8")
            with self.assertRaises(ValueError) as cm:
                read_csv(str(path))
            self.assertIn("category", str(cm.exception))

    def test_read_csv_empty_payee(self):
        bad_csv = self.csv_content.replace("Shell", "")
        with TemporaryDirectory() as tmpdir:
            path = Path(tmpdir) / "empty_payee.csv"
            path.write_text(bad_csv, encoding="utf-8")
            with self.assertRaises(RuntimeError):
                read_csv(str(path))


